1	import { Editor } from "obsidian";
2	import { DiscourseNode } from "~/types";
3	
4	type NodeTagItem = {
5	  nodeType: DiscourseNode;
6	  tag: string;
7	};
8	
9	export class NodeTagSuggestPopover {
10	  private popover: HTMLElement | null = null;
11	  private items: NodeTagItem[] = [];
12	  private selectedIndex = 0;
13	  private keydownHandler: ((e: KeyboardEvent) => void) | null = null;
14	  private clickOutsideHandler: ((e: MouseEvent) => void) | null = null;
15	
16	  constructor(
17	    private editor: Editor,
18	    private nodeTypes: DiscourseNode[],
19	  ) {
20	    this.initializeItems();
21	  }
22	
23	  private initializeItems() {
24	    this.items = [];
25	    this.nodeTypes.forEach((nodeType) => {
26	      if (nodeType.tag) {
27	        this.items.push({
28	          nodeType,
29	          tag: nodeType.tag,
30	        });
31	      }
32	    });
33	  }
34	
35	  private getCursorPosition(): { x: number; y: number } | null {
36	    try {
37	      const selection = window.getSelection();
38	      if (!selection || selection.rangeCount === 0) {
39	        console.error("No selection found");
40	        return null;
41	      }
42	
43	      const range = selection.getRangeAt(0);
44	      const rect = range.getBoundingClientRect();
45	
46	      // If the rect has no dimensions (collapsed cursor), try using a temporary span to get cursor position
47	      if (rect.width === 0 && rect.height === 0) {
48	        const span = activeDocument.createElement("span");
49	        span.textContent = "\u200B";
50	        range.insertNode(span);
51	        const spanRect = span.getBoundingClientRect();
52	        span.remove();
53	
54	        if (spanRect.width === 0 && spanRect.height === 0) {
55	          console.error("Could not determine cursor position");
56	          return null;
57	        }
58	
59	        return {
60	          x: spanRect.left,
61	          y: spanRect.bottom,
62	        };
63	      }
64	
65	      return {
66	        x: rect.left,
67	        y: rect.bottom,
68	      };
69	    } catch (error) {
70	      console.error("Error getting cursor position:", error);
71	      return null;
72	    }
73	  }
74	
75	  private createPopover(): HTMLElement {
76	    const popover = activeDocument.createElement("div");
77	    popover.className =
78	      "node-tag-suggest-popover fixed z-[10000] bg-primary border border-modifier-border rounded-md shadow-[0_4px_12px_rgba(0,0,0,0.15)] max-h-[300px] overflow-y-auto min-w-[200px] max-w-[400px]";
79	
80	    const itemsContainer = activeDocument.createElement("div");
81	    itemsContainer.className = "node-tag-items-container";
82	    popover.appendChild(itemsContainer);
83	
84	    this.renderItems(itemsContainer);
85	
86	    return popover;
87	  }
88	
89	  private renderItems(container: HTMLElement) {
90	    container.innerHTML = "";
91	
92	    if (this.items.length === 0) {
93	      const noResults = activeDocument.createElement("div");
94	      noResults.className = "p-3 text-center text-muted text-sm";
95	      noResults.textContent = "No node tags available";
96	      container.appendChild(noResults);
97	      return;
98	    }
99	
100	    this.items.forEach((item, index) => {
101	      const itemEl = activeDocument.createElement("div");
102	      itemEl.className = `node-tag-item px-3 py-2 cursor-pointer flex items-center gap-2 border-b border-[var(--background-modifier-border-hover)]${
103	        index === this.selectedIndex ? " bg-modifier-hover" : ""
104	      }`;
105	      itemEl.dataset.index = index.toString();
106	
107	      if (item.nodeType.color) {
108	        const colorDot = activeDocument.createElement("div");
109	        colorDot.className = `w-3 h-3 rounded-full shrink-0`;
110	        colorDot.style.backgroundColor = item.nodeType.color;
111	        itemEl.appendChild(colorDot);
112	      }
113	
114	      const textContainer = activeDocument.createElement("div");
115	      textContainer.className = "flex flex-col gap-0.5 flex-1";
116	
117	      const tagText = activeDocument.createElement("div");
118	      tagText.textContent = `#${item.tag}`;
119	      tagText.className = "font-medium text-normal text-sm";
120	
121	      const nodeTypeText = activeDocument.createElement("div");
122	      nodeTypeText.textContent = item.nodeType.name;
123	      nodeTypeText.className = "text-xs text-muted";
124	
125	      textContainer.appendChild(tagText);
126	      textContainer.appendChild(nodeTypeText);
127	      itemEl.appendChild(textContainer);
128	
129	      itemEl.addEventListener("mousedown", (e) => {
130	        e.preventDefault();
131	        e.stopPropagation();
132	        this.selectItem(item);
133	      });
134	
135	      itemEl.addEventListener("mouseenter", () => {
136	        this.updateSelectedIndex(index);
137	      });
138	
139	      container.appendChild(itemEl);
140	    });
141	  }
142	
143	  private updateSelectedIndex(newIndex: number) {
144	    if (newIndex === this.selectedIndex) return;
145	
146	    const prevSelected = this.popover?.querySelector(
147	      `.node-tag-item[data-index="${this.selectedIndex}"]`,
148	    ) as HTMLElement;
149	    if (prevSelected) {
150	      prevSelected.classList.remove("bg-modifier-hover");
151	    }
152	
153	    this.selectedIndex = newIndex;
154	
155	    const newSelected = this.popover?.querySelector(
156	      `.node-tag-item[data-index="${this.selectedIndex}"]`,
157	    ) as HTMLElement;
158	    if (newSelected) {
159	      newSelected.classList.add("bg-modifier-hover");
160	    }
161	  }
162	
163	  private scrollToSelected() {
164	    const selectedEl = this.popover?.querySelector(
165	      `.node-tag-item[data-index="${this.selectedIndex}"]`,
166	    ) as HTMLElement;
167	    if (selectedEl) {
168	      selectedEl.scrollIntoView({ block: "nearest", behavior: "smooth" });
169	    }
170	  }
171	
172	  private selectItem(item: NodeTagItem) {
173	    const tagText = `#${item.tag} `;
174	    const cursor = this.editor.getCursor();
175	    this.editor.replaceRange(tagText, cursor, cursor);
176	    const newCursor = {
177	      line: cursor.line,
178	      ch: cursor.ch + tagText.length,
179	    };
180	    this.editor.setCursor(newCursor);
181	    this.close();
182	  }
183	
184	  private setupEventHandlers() {
185	    this.keydownHandler = (e: KeyboardEvent) => {
186	      if (!this.popover) return;
187	
188	      if (e.key === "ArrowDown") {
189	        e.preventDefault();
190	        e.stopPropagation();
191	        const newIndex = Math.min(
192	          this.selectedIndex + 1,
193	          this.items.length - 1,
194	        );
195	        this.updateSelectedIndex(newIndex);
196	        this.scrollToSelected();
197	      } else if (e.key === "ArrowUp") {
198	        e.preventDefault();
199	        e.stopPropagation();
200	        const newIndex = Math.max(this.selectedIndex - 1, 0);
201	        this.updateSelectedIndex(newIndex);
202	        this.scrollToSelected();
203	      } else if (e.key === "Enter") {
204	        e.preventDefault();
205	        e.stopPropagation();
206	        const selectedItem = this.items[this.selectedIndex];
207	        if (selectedItem) {
208	          this.selectItem(selectedItem);
209	        }
210	      } else if (e.key === "Escape") {
211	        e.preventDefault();
212	        e.stopPropagation();
213	        this.close();
214	      }
215	    };
216	
217	    this.clickOutsideHandler = (e: MouseEvent) => {
218	      if (
219	        this.popover &&
220	        !this.popover.contains(e.target as Node) &&
221	        !(e.target as HTMLElement).closest(".node-tag-suggest-popover")
222	      ) {
223	        this.close();
224	      }
225	    };
226	
227	    activeDocument.addEventListener("keydown", this.keydownHandler, true);
228	    activeDocument.addEventListener(
229	      "mousedown",
230	      this.clickOutsideHandler,
231	      true,
232	    );
233	  }
234	
235	  private removeEventHandlers() {
236	    if (this.keydownHandler) {
237	      activeDocument.removeEventListener("keydown", this.keydownHandler, true);
238	      this.keydownHandler = null;
239	    }
240	    if (this.clickOutsideHandler) {
241	      activeDocument.removeEventListener(
242	        "mousedown",
243	        this.clickOutsideHandler,
244	        true,
245	      );
246	      this.clickOutsideHandler = null;
247	    }
248	  }
249	
250	  public open() {
251	    if (this.popover) {
252	      this.close();
253	    }
254	
255	    const position = this.getCursorPosition();
256	    if (!position) {
257	      console.error("Could not get cursor position for popover");
258	      return;
259	    }
260	
261	    this.popover = this.createPopover();
262	    activeDocument.body.appendChild(this.popover);
263	
264	    const popoverRect = this.popover.getBoundingClientRect();
265	    const viewportWidth = window.innerWidth;
266	    const viewportHeight = window.innerHeight;
267	
268	    let left = position.x;
269	    let top = position.y + 4;
270	
271	    if (left + popoverRect.width > viewportWidth) {
272	      left = viewportWidth - popoverRect.width - 10;
273	    }
274	    if (left < 10) {
275	      left = 10;
276	    }
277	
278	    if (top + popoverRect.height > viewportHeight) {
279	      // Position above cursor instead
280	      top = position.y - popoverRect.height - 4;
281	    }
282	    if (top < 10) {
283	      top = 10;
284	    }
285	
286	    this.popover.style.left = `${left}px`;
287	    this.popover.style.top = `${top}px`;
288	
289	    this.setupEventHandlers();
290	  }
291	
292	  public close() {
293	    this.removeEventHandlers();
294	    if (this.popover) {
295	      this.popover.remove();
296	      this.popover = null;
297	    }
298	    this.selectedIndex = 0;
299	  }
300	}
