  query: string,
): DiscourseNode[] => {
  const trimmedQuery = query.trim().toLowerCase();
  if (!trimmedQuery) return nodeTypes;

  return nodeTypes.filter((nodeType) =>
    nodeType.name.toLowerCase().includes(trimmedQuery),
  );
};
